begin;
do $fixture$
declare academy uuid:=gen_random_uuid();owner_id uuid:=gen_random_uuid();peer uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();class_a uuid:=gen_random_uuid();class_b uuid:=gen_random_uuid();class_c uuid:=gen_random_uuid();room_a uuid:=gen_random_uuid();room_c uuid:=gen_random_uuid();staff_a uuid:=gen_random_uuid();staff_b uuid:=gen_random_uuid();contact_a uuid:=gen_random_uuid();contact_b uuid:=gen_random_uuid();grant_a uuid;payload jsonb;result jsonb;saved jsonb;box uuid;shift uuid;plan uuid;subscription uuid;charge uuid;before_count integer;
begin
 insert into auth.users(id,email,aud,role,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) select id,id||'@example.invalid','authenticated','authenticated',now(),'{"provider":"email","providers":["email"]}','{"full_name":"Owned booking collection"}' from unnest(array[owner_id,peer]) id;
