 insert into public.academy_classrooms(id,academy_id,branch_id,name,created_by) values(class_a,academy,a,'Owned A',owner_id),(class_b,academy,b,'Owned B',owner_id),(class_c,academy,a,'Owned C',owner_id);
 insert into public.academy_rooms(id,academy_id,branch_id,room_key,name,capacity) values(room_a,academy,a,'owned-a','Owned A',30),(room_c,academy,a,'owned-c','Owned C',30);
 insert into public.academy_staff(id,academy_id,email,display_name,role,classroom_ids,created_by) values(staff_a,academy,'owned-a-'||academy||'@example.invalid','Owned A','teacher',jsonb_build_array(class_a),owner_id),(staff_b,academy,'owned-b-'||academy||'@example.invalid','Owned B','teacher',jsonb_build_array(class_b,class_c),owner_id);
 insert into public.academy_contacts(id,academy_id,primary_branch_id,first_name,status,notify_enabled,created_by) values(contact_a,academy,a,'Owned learner A','active',false,owner_id),(contact_b,academy,b,'Owned learner B','active',false,owner_id);
 insert into public.academy_role_grants(academy_id,user_id,email,role,scope_type,scope_ids,status,granted_by) values(academy,peer,peer||'-manager@example.invalid','manager','branches',jsonb_build_array(b),'active',owner_id);
 insert into public.academy_role_grants(academy_id,user_id,email,role,scope_type,scope_ids,status,granted_by) values(academy,peer,peer||'-cashier@example.invalid','cashier','branches',jsonb_build_array(a),'active',owner_id) returning id into grant_a;
 payload:=jsonb_build_object('branch_id',a,'classroom_id',class_a,'room_id',room_a,'primary_staff_id',staff_a,'title','Owned accepted booking','delivery_mode','physical','session_type','regular','starts_at',date_trunc('hour',clock_timestamp())+interval '10 days','ends_at',date_trunc('hour',clock_timestamp())+interval '10 days 1 hour','timezone','Asia/Tashkent');
 begin perform public.academy_booking_command(academy,peer,payload,'owned-forbidden-booking');raise exception 'Mixed roles promoted cashier A into booking';exception when insufficient_privilege then null;end;
 result:=public.academy_booking_command(academy,owner_id,payload,'owned-booking');saved:=result;
 if result->>'replayed' is distinct from 'false' or result->'session'->>'classroom_id' is distinct from class_a::text then raise exception 'Legitimate lesson was not accepted';end if;
 result:=public.academy_booking_command(academy,owner_id,payload,'owned-booking');if result->>'replayed' is distinct from 'true' or result->'session'->>'id' is distinct from saved->'session'->>'id' then raise exception 'Booking retry duplicated';end if;
 begin perform public.academy_booking_command(academy,owner_id,payload||'{"title":"Changed"}','owned-booking');raise exception 'Booking key changed payload';exception when unique_violation then null;end;
 begin perform public.academy_booking_command(academy,owner_id,payload||jsonb_build_object('classroom_id',class_c,'primary_staff_id',staff_b),'owned-room-clash');raise exception 'Room clash accepted';exception when exclusion_violation then null;end;
 begin perform public.academy_booking_command(academy,owner_id,payload||jsonb_build_object('classroom_id',class_c,'room_id',room_c),'owned-teacher-clash');raise exception 'Teacher clash accepted';exception when exclusion_violation then null;end;
 begin perform public.academy_booking_command(academy,owner_id,payload||jsonb_build_object('room_id',room_c,'primary_staff_id',staff_b),'owned-class-clash');raise exception 'Class clash accepted';exception when exclusion_violation then null;end;
 if (select count(*) from public.academy_lesson_sessions where academy_id=academy)<>1 or(select count(*) from public.academy_operational_command_receipts where academy_id=academy)<>1 then raise exception 'Failed bookings left partial rows or receipts';end if;
 result:=public.academy_finance_command(academy,owner_id,'create_pricing_plan',jsonb_build_object('plan_key','owned-tuition','name','Owned tuition','pricing_model','monthly_fixed','billing_cycle','monthly','base_amount',5000,'currency','UZS','branch_id',a,'classroom_id',class_a),'owned-plan');plan:=(result->'pricing_plan'->>'id')::uuid;
 result:=public.academy_finance_command(academy,owner_id,'create_subscription',jsonb_build_object('contact_id',contact_a,'pricing_plan_id',plan,'branch_id',a,'classroom_id',class_a,'status','active','starts_on',current_date,'ends_on',current_date+30,'list_amount',5000),'owned-subscription');subscription:=(result->'subscription'->>'id')::uuid;
 result:=public.academy_finance_command(academy,owner_id,'create_charge',jsonb_build_object('subscription_id',subscription,'cycle_key','owned-cycle','issued_on',current_date,'due_on',current_date,'original_amount',5000,'description','Owned collection charge'),'owned-charge');charge:=(result->'charge'->>'id')::uuid;
 result:=public.academy_finance_command(academy,owner_id,'create_cashbox',jsonb_build_object('branch_id',a,'name','Owned collection box','currency','UZS'),'owned-box');box:=(result->'cashbox'->>'id')::uuid;
 result:=public.academy_finance_command(academy,owner_id,'open_cashier_shift',jsonb_build_object('cashbox_id',box,'opening_balance',100),'owned-shift');shift:=(result->'cashier_shift'->>'id')::uuid;
 payload:=jsonb_build_object('contact_id',contact_a,'shift_id',shift,'charge_id',charge,'amount','3000','currency','UZS','payment_method','cash','reason','Owned physical receipt');
 begin perform public.academy_collect_student_payment(academy,peer,payload,'owned-foreign-custody');raise exception 'Collected in someone else shift';exception when unique_violation then null;end;
 result:=public.academy_collect_student_payment(academy,owner_id,payload,'owned-cash');saved:=result;
 if result->'payment'->>'amount' is distinct from '3000' or result->'ledger_entry'->>'amount' is distinct from '-3000' or result->'cash_movement'->>'academy_payment_id' is distinct from result->'payment'->>'id' or result->'allocation'->>'amount' is distinct from '3000' then raise exception 'Collection evidence was not exact and linked';end if;
 result:=public.academy_collect_student_payment(academy,owner_id,payload,'owned-cash');if result->>'replayed' is distinct from 'true' or result->'payment'->>'id' is distinct from saved->'payment'->>'id' then raise exception 'Collection retry duplicated';end if;
 result:=public.academy_collect_student_payment(academy,owner_id,payload||'{"amount":"2000","payment_method":"manual_pos"}','owned-card');
 if result->'payment'->>'provider' is distinct from 'manual_pos' or(select status from public.academy_charges where id=charge)<>'paid' then raise exception 'Manual card receipt did not settle its internal charge';end if;
 select count(*) into before_count from public.academy_payments where academy_id=academy;
 begin perform public.academy_collect_student_payment(academy,owner_id,payload||'{"amount":"1"}','owned-excess-allocation');raise exception 'Over-allocation accepted';exception when raise_exception then if sqlerrm='Over-allocation accepted' then raise;end if;end;
 if (select count(*) from public.academy_payments where academy_id=academy)<>before_count or(select count(*) from public.academy_cash_movements where academy_id=academy)<>2 or(select count(*) from public.academy_account_ledger_entries where academy_id=academy and entry_type='payment_received')<>2 then raise exception 'Rejected allocation left partial collection evidence';end if;
 begin perform public.academy_collect_student_payment(academy,owner_id,payload||'{"payment_method":"click"}','owned-forged-click');raise exception 'Manual collection forged Click funding';exception when invalid_parameter_value then null;end;
 begin perform public.academy_collect_student_payment(academy,owner_id,payload||'{"amount":"2147483648"}','owned-overflow');raise exception 'Manual payment overflow accepted';exception when invalid_parameter_value then null;end;
 begin perform public.academy_collect_student_payment(academy,owner_id,payload||jsonb_build_object('contact_id',contact_b,'charge_id',null),'owned-cross-branch');raise exception 'Foreign branch student used another branch shift';exception when invalid_parameter_value then null;end;
 result:=public.academy_finance_command(academy,owner_id,'close_cashier_shift',jsonb_build_object('shift_id',shift,'counted_closing_balance','3100','reason','Owned close'),'owned-close');
 if result->'shift'->>'expected_closing_balance' is distinct from '3100' then raise exception 'Card receipts changed physical cash expectation';end if;
 result:=public.academy_collect_student_payment(academy,owner_id,payload,'owned-cash');if result->>'replayed' is distinct from 'true' then raise exception 'Closed shift lost original collection receipt';end if;
 if has_function_privilege('authenticated','public.academy_booking_command(uuid,uuid,jsonb,text)','EXECUTE') or has_function_privilege('authenticated','public.academy_collect_student_payment(uuid,uuid,jsonb,text)','EXECUTE') then raise exception 'Browser bypasses command actor boundary';end if;
